    }

    // Method to reverse a linked list.
    static Node reverseList(Node head) {
        if (head == null || head.next == null) {
            return head;  // Return the same node as it is already reversed
        }

        Node prev = null;
        Node curr = head;

        while (curr != null && curr.next != null) {
            Node next = curr.next;
            curr.next = prev;
            prev = curr;
            curr = next;
        }
        return prev;  // Return the new first node of reversed list
    }

